CREATE TABLE sheep (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL, tag_number VARCHAR(80) NOT NULL, birth_month VARCHAR(20), birth_year INTEGER, sex VARCHAR(30), notes TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_sheep_farm_tag UNIQUE(farm_id,tag_number), CONSTRAINT ck_sheep_status CHECK(status IN ('ACTIVE','DECEASED','SOLD','TRANSFERRED','INACTIVE')));
CREATE INDEX ix_sheep_farm ON sheep(farm_id); CREATE INDEX ix_sheep_birth ON sheep(birth_year,birth_month);
CREATE TABLE medications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL UNIQUE, category VARCHAR(100), administration_type VARCHAR(100), standard_dosage TEXT, withdrawal_days INTEGER CHECK(withdrawal_days IS NULL OR withdrawal_days >= 0), dosing_frequency TEXT, treats TEXT, notes TEXT, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE treatments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), farm_id UUID NOT NULL, sheep_id UUID NOT NULL REFERENCES sheep(id), medication_id UUID NOT NULL REFERENCES medications(id), administered_at DATE NOT NULL, dose_amount NUMERIC(12,3) NOT NULL CHECK(dose_amount > 0), dose_unit VARCHAR(30) NOT NULL, withdrawal_days_applied INTEGER CHECK(withdrawal_days_applied IS NULL OR withdrawal_days_applied >= 0), withdrawal_until DATE, administered_by VARCHAR(160), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_treatment_farm_date ON treatments(farm_id,administered_at); CREATE INDEX ix_treatment_sheep_date ON treatments(sheep_id,administered_at DESC); CREATE INDEX ix_treatment_medication ON treatments(medication_id);